data = []
for i in range(0, 100):
    data.append(os.urandom(64))


def speed_test(_hash, iterations=10):
    results = []

    for i in range(0, iterations):
        for i in data:
            start = time.time()
            r = list(fastcdc(i, 4096, 8192, 16384, hf=_hash))
            results.append(time.time() - start)
            print(results[len(results)-1])

    return statistics.mean(results)


sha26 = speed_test(hashlib.sha256)
print("sha256 = " + str(sha26))

blake2b = speed_test(_blake2.blake2b)
print("blake2b = " + str(blake2b))

blake3 = speed_test(blake3.blake3)
print("blake3 = " + str(blake3))

xxhash32 = speed_test(xxhash.xxh32)
print("xxhahs32 = " + str(xxhash32))

xxhash64 = speed_test(xxhash.xxh64)
print("xxhash64 = " + str(xxhash64))

xxhaash3_64 = speed_test(xxhash.xxh3_64)
print("xxhash3_64 = " + str(xxhaash3_64))

xxhaash3_128 = speed_test(xxhash.xxh3_128)
